SELECT 'gongkao', '船速水速反求', 'kp-trv-boat-reverse', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "船速水速反求"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "给出两段航行的时间或距离，建立方程反解 V船 或 V水。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“某船顺水航行 120km 用了 4 小时，逆水航行同样距离用了 6 小时。求船在静水中的速度？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[先求出整体的综合速度] --> B[V顺 = S顺 ÷ T顺 = 120 / 4 = 30]\nB --> C[V逆 = S逆 ÷ T逆 = 120 / 6 = 20]\nC --> D[套用船速反求公式: V船 = (V顺 + V逆) ÷ 2]\nD --> E[(30+20) ÷ 2 = 25]"}}]}$$ AS jsonb), NULL, '船速水速反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "船速水速反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_boat_reverse", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
